package com.villofarm.controller;import com.villofarm.model.Product;import com.villofarm.repository.ProductRepository;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/products") public class ProductController {private final ProductRepository products;public ProductController(ProductRepository products){this.products=products;}@GetMapping public List<Product> all(){return products.findByActiveTrueOrderByIdAsc();}}
